from collections import defaultdict

cells = [(5, 5), (5, 6), (5, 7), (6, 7), (7, 7), (7, 6), (7, 5), (6, 5)]

def build_graph(cells):
    s = set(cells)
    g = defaultdict(list)
    for r, c in cells:
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if (nr, nc) in s:
                g[(r, c)].append((nr, nc))
    return g

# Backtracking Hamiltonian cycle search

def find_cycle(graph, start):
    n = len(graph)
    path = [start]
    visited = {start}
    def dfs(cur):
        if len(path) == n:
            # close cycle
            if start in graph[cur]:
                path.append(start)
                return True
            return False
        for nxt in graph[cur]:
            if nxt not in visited:
                visited.add(nxt)
                path.append(nxt)
                if dfs(nxt):
                    return True
                path.pop()
                visited.remove(nxt)
        return False
    return path if dfs(start) else None

graph = build_graph(cells)
cycle = None
for st in cells:
    res = find_cycle(graph, st)
    if res:
        cycle = res
        break

if cycle:
    print('Answer: Yes')
    print('Explanation: A Hamiltonian cycle exists among the extracted green cells.')
    print('Path:', cycle)
else:
    print('Answer: No')
    print('Explanation: No Hamiltonian cycle found among the extracted green cells.')

